const WEB4_ONLY = /^web ?4$/i;
const WEB4_TOKEN = "web4";
const TOKEN_TOKENS = new Set(tokenize("compute token tokens coin sol solana"));
const DELETE_TOKEN = tokenize("delete")[0];
const FILE_TOKEN = tokenize("files")[0];
export function bestMatch(question, index) {
    const exact = looseKey(question);
    for (let c = 0; c < index.cards.length; c++) {
        if (index.docs[c].some((d) => d.exact === exact))
            return { card: index.cards[c], score: 1, coverage: 1 };
    }
    let q = [...new Set(tokenize(question).map((t) => correct(t, index)))];
    if (q.length === 0 && /\bweb ?4\b/.test(normalizeText(question)))
        q = [WEB4_TOKEN];
    if (q.length === 0)
        return null;
    const w = (t) => index.idf.get(t) ?? (/^\d+$/.test(t) ? 0.5 : index.unknownWeight);
    const total = q.reduce((s, t) => s + w(t), 0);
    let best = null;
    let bestRecall = -1;
    let bestHit = [];
    const anchors = anchorsOf(question);
    const deletesToken = q.includes(DELETE_TOKEN) && !q.includes(FILE_TOKEN) && q.some((t) => TOKEN_TOKENS.has(t));
    for (let c = 0; c < index.cards.length; c++) {
        if (anchors.some((a) => a.topic !== index.cards[c].topic && !index.cardTokens[c].has(a.token)))
            continue;
        if (deletesToken && index.cards[c].topic === "rent" && ![...TOKEN_TOKENS].some((t) => index.cardTokens[c].has(t)))
            continue;
        for (const d of index.docs[c]) {
            const hit = q.filter((t) => d.tokens.has(t));
            if (hit.length === 0)
                continue;
            const coverage = hit.reduce((s, t) => s + w(t), 0) / total;
            const qTotal = d.questionTokens.reduce((s, t) => s + w(t), 0) || 1;
            const recall = d.questionTokens.filter((t) => q.includes(t)).reduce((s, t) => s + w(t), 0) / qTotal;
            const score = 0.8 * coverage + 0.2 * recall;
            if (!best || score > best.score || (score === best.score && recall > bestRecall)) {
                best = { card: index.cards[c], score, coverage };
                bestRecall = recall;
                bestHit = hit;
            }
        }
    }
    if (!best || best.coverage < MIN_COVERAGE || best.score < MIN_SCORE)
        return null;
    const named = latinFold(normalizeText(tickerCase(question)));
    if (TOKEN_NAMED.test(named)) {
        const figToken = /\$fig\b|\bfig ?(tokens?|coins?)\b/.test(named);
        const content = bestHit.filter((t) => !TOKEN_TOKENS.has(t) && !(figToken && t === "fig"));
        if (content.length === 0)
            return null;
    }
    return best;
}
export function ask(question, index) {
    if (!normalizeText(question))
        return { kind: "empty" };
    if (isSeedQuestion(question))
        return { kind: "refused", reason: "seed", reply: SEED_REPLY };
    if (isMoneyQuestion(question))
        return { kind: "refused", reason: "money", reply: REFUSAL_REPLY };
    if (question.length > MAX_QUESTION_CHARS)
        return { kind: "unknown" };
    if (UNREAD.test(latinFold(normalizeText(question))))
        return isMoneyShaped(question) ? { kind: "refused", reason: "money", reply: REFUSAL_REPLY } : { kind: "unknown" };
    const figToken = isFigTokenQuestion(question) ? index.cards.find((c) => c.id === FIG_TOKEN_CARD) : undefined;
    if (figToken)
        return { kind: "answer", card: figToken, score: 1 };
    const m = bestMatch(question, index);
    if (m)
        return { kind: "answer", card: m.card, score: m.score };
    return isMoneyShaped(question) ? { kind: "refused", reason: "money", reply: REFUSAL_REPLY } : { kind: "unknown" };
}
const DAY_MS = 86400000;
const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
export function parseDay(day) {
    const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(day);
    if (!m)
        return NaN;
    const t = Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3]));
    return new Date(t).toISOString().slice(0, 10) === day ? t : NaN;
}
export function formatDay(day) {
    const t = parseDay(day);
    if (Number.isNaN(t))
        return day;
    const d = new Date(t);
    return `${MONTHS[d.getUTCMonth()]} ${d.getUTCDate()}, ${d.getUTCFullYear()}`;
}
export function staleAt(card) {
    return parseDay(card.verified_at) + card.ttl_days * DAY_MS;
}
export function isStale(card, now) {
    return now > staleAt(card);
}
